'use strict'

const expandPath = require('@antora/expand-path-helper')
const { promises: fsp } = require('node:fs')
const mkdirp = (path) => fsp.mkdir(path, { recursive: true })
const rmrf = (path) => fsp.rm(path, { recursive: true, force: true })
const ospath = require('node:path')
const { pathToFileURL } = require('node:url')
const publishStream = require('./common/publish-stream')
const { Writable } = require('node:stream')
const forEach = (write, final) => new Writable({ objectMode: true, write, final })

const { DEFAULT_DEST_FS } = require('../constants.js')
const invariably = { void: () => undefined }

function publishToFs (config, files, playbook) {
  const destDir = config.path || DEFAULT_DEST_FS
  const absDestDir = expandPath(destDir, { dot: playbook.dir })
  return (config.clean ? rmrf(absDestDir).then(() => mkdirp(absDestDir)) : mkdirp(absDestDir))
    .then(() => publishStream(fsDest(absDestDir), files))
    .then(() => ({ provider: 'fs', path: destDir, resolvedPath: absDestDir, fileUri: pathToFileURL(absDestDir).href }))
}

function fsDest (toDir) {
  const ensureDir = createEnsureDir(toDir)
  return forEach((file, _, done) => {
    if (file.isNull()) return done()
    const abspath = ospath.join(toDir, file.path)
    ensureDir(ospath.dirname(abspath))
      .then(async () => {
        const { gid, mode, uid } = file.stat || {}
        const fh = await fsp.open(abspath, 'w', mode)
        try {
          await fh.writeFile(file.contents)
          const stat = await fh.stat()
          if (typeof mode === 'number' && (mode & 0o7777) !== (stat.mode & 0o7777)) await fh.chmod(mode)
          const { gid: fGid, uid: fUid } = stat
          const targetUid = typeof uid === 'number' && uid >= 0 ? uid : fUid
          const targetGid = typeof gid === 'number' && gid >= 0 ? gid : fGid
          if (targetUid !== fUid || targetGid !== fGid) await fh.chown(targetUid, targetGid).catch(invariably.void)
        } finally {
          await fh.close().catch(invariably.void)
        }
      })
      .then(done, done)
  })
}

function createEnsureDir (baseDir) {
  const cache = new Set([baseDir])
  return (dir) => {
    if (cache.has(dir)) return Promise.resolve()
    const leafDir = dir
    do {
      cache.add(dir)
      const ancestor = ospath.dirname(dir)
      if (ancestor === dir) break
      dir = ancestor
    } while (!cache.has(dir))
    return mkdirp(leafDir)
  }
}

module.exports = publishToFs
